#!/usr/bin/env node
/**
 * Exports the approved static wordmark (F1–F6 final: R2 + E2 + K2 + D2) as SVG files,
 * plus src/brand/wordmark.generated.ts.
 *
 *   node scripts/export-wordmark.mjs            write the files
 *   node scripts/export-wordmark.mjs --verify   regenerate in memory and compare with what is committed
 *
 * Options: --root <dir> (default: cwd). The reference HTML is read from <root>/docs/reference/.
 * Generated files must never be edited by hand; change the reference, then re-export.
 *
 * Variants: pair | bi | ar | en   ×   light (ink #0E3A5F + accent #1F5FA8) | solid (ink only).
 * Light backgrounds only (Sand or white). No dark, reversed, or monochrome versions in V1.
 */
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { loadReference } from './lib/reference-wordmark.mjs';

const args = process.argv.slice(2);
const VERIFY = args.includes('--verify');
const rootIdx = args.indexOf('--root');
const ROOT = path.resolve(rootIdx >= 0 && args[rootIdx + 1] ? args[rootIdx + 1] : process.cwd());
const REF = path.join(ROOT, 'docs/reference/wordmark-exploration-F1-F6.html');
const SVG_DIR = 'src/brand/assets/wordmark';
const TS_FILE = 'src/brand/wordmark.generated.ts';

const INK = '#0E3A5F';
const ACCENT = '#1F5FA8';
const UNIT = 1000; // internal drawing width: the Arabic word is 1000 units wide in every variant
const KINDS = ['pair', 'bi', 'ar', 'en'];
const LABEL = { pair: 'مِيدان Midan', bi: 'مِيدان Midan', ar: 'مِيدان', en: 'Midan' };

const fail = (msg) => {
  console.error(`✘ ${msg}`);
  process.exit(1);
};

if (!fs.existsSync(REF)) fail(`Reference file not found: ${REF}`);
const ref = loadReference(REF);
const P = ref.FP();
if (P.p !== INK || P.s !== ACCENT) fail(`Reference colors changed (ink ${P.p}, accent ${P.s}); expected ${INK} / ${ACCENT}.`);
const PALETTES = { light: P, solid: { ...P, s: INK } };

function build(kind, mode) {
  const raw = ref.wm('fin', kind, UNIT, 'light', PALETTES[mode]);
  const head = /^<svg viewBox="0 0 ([\d.]+) ([\d.]+)" width="[^"]*" height="[^"]*" role="img" aria-label="[^"]*">/.exec(raw);
  if (!head || !raw.endsWith('</svg>')) fail(`Unexpected SVG shape for ${kind}/${mode}`);
  const [open, w, h] = head;
  const inner = raw.slice(open.length, -'</svg>'.length);
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="${LABEL[kind]}">` +
    `${inner}</svg>\n`;

  if (/midan/.test(svg)) fail(`${kind}/${mode}: lowercase "midan" found; the English wordmark is "Midan".`);
  const fills = new Set([...svg.matchAll(/fill="([^"]+)"/g)].map((m) => m[1]));
  const allowed = mode === 'light' ? [INK, ACCENT] : [INK];
  for (const f of fills) if (!allowed.includes(f)) fail(`${kind}/${mode}: unexpected fill ${f}`);
  if (mode === 'light' && !fills.has(ACCENT)) fail(`${kind}/${mode}: accent color missing`);
  if (/<text|<image|<script|href=|url\(/.test(svg)) fail(`${kind}/${mode}: svg must be plain paths only`);
  return { svg, width: Number(w), height: Number(h) };
}

const files = new Map(); // relative path -> contents
const meta = {};
for (const kind of KINDS) {
  meta[kind] = {};
  for (const mode of ['light', 'solid']) {
    const out = build(kind, mode);
    files.set(`${SVG_DIR}/midan-wordmark-${kind}-${mode}.svg`, out.svg);
    meta[kind].width = out.width;
    meta[kind].height = out.height;
  }
}

const cap = (s) => s[0].toUpperCase() + s.slice(1);
const imports = KINDS.flatMap((k) => ['light', 'solid'].map((m) => `import ${k}${cap(m)} from './assets/wordmark/midan-wordmark-${k}-${m}.svg';`));
const entries = KINDS.map(
  (k) =>
    `  ${k}: { light: ${k}Light, solid: ${k}Solid, width: ${meta[k].width}, height: ${meta[k].height}, aspect: ${(meta[k].width / meta[k].height).toFixed(6)} },`,
);
files.set(
  TS_FILE,
  `/* GENERATED by scripts/export-wordmark.mjs from docs/reference/wordmark-exploration-F1-F6.html. Do not edit by hand. */\n${imports.join('\n')}\n\n` +
    `export const WORDMARK_ASSETS = {\n${entries.join('\n')}\n} as const;\n\nexport type WordmarkVariant = keyof typeof WORDMARK_ASSETS;\n`,
);

if (!VERIFY) {
  fs.mkdirSync(path.join(ROOT, SVG_DIR), { recursive: true });
  for (const [rel, body] of files) fs.writeFileSync(path.join(ROOT, rel), body);
  for (const [rel, body] of files) console.log(`• ${rel}  (${Buffer.byteLength(body)} bytes)`);
  console.log(`✔ Exported ${files.size} files from the reference.`);
  process.exit(0);
}

const problems = [];
for (const [rel, body] of files) {
  const p = path.join(ROOT, rel);
  if (!fs.existsSync(p)) problems.push(`${rel}: missing`);
  else if (fs.readFileSync(p, 'utf8') !== body) problems.push(`${rel}: differs from a fresh export of the reference`);
}
const dir = path.join(ROOT, SVG_DIR);
if (fs.existsSync(dir)) {
  for (const f of fs.readdirSync(dir)) if (!files.has(`${SVG_DIR}/${f}`)) problems.push(`${SVG_DIR}/${f}: not produced by the export (stale or hand-made)`);
}
if (problems.length) fail(`Wordmark verification failed:\n  ${problems.join('\n  ')}`);
console.log(`✔ ${files.size} wordmark files match a fresh export of the reference.`);
